///////////////////////////////////////////////////////////////
// FULL SHADERTOY CODE: 
//  - Hinged ring animation from t=0..9
//  - Pause from t=9..13
//  - Repeat
//  - No pivot shift at the start (spin around origin)
///////////////////////////////////////////////////////////////

float PI = 3.14159265359;

//-----------------------------------------
// rotateY
//-----------------------------------------
mat3 rotateY(float a)
{
    float c = cos(a), s = sin(a);
    return mat3(
       c,  0.,  s,
       0.,  1.,  0.,
      -s,  0.,  c
    );
}

//-----------------------------------------
// rotateZ (used by camera if needed)
//-----------------------------------------
mat3 rotateZ(float a)
{
    float c = cos(a), s = sin(a);
    return mat3(
        c, -s,  0.,
        s,  c,  0.,
        0., 0., 1.
    );
}

//-----------------------------------------
// sdWireCircle: a "wire" ring in XY-plane
//-----------------------------------------
float sdWireCircle(vec3 p, float R, float w)
{
    // distance in the XY-plane minus ring radius
    float distXY = length(p.xy) - R;
    // combine with Z => thick tube around circle
    return sqrt(distXY*distXY + p.z*p.z) - w;
}

//-----------------------------------------
// Hinged ring logic: top & bottom half
//-----------------------------------------
float getHingedRingSDF(vec3 pLocal, float R, float wt, float hingeAngle)
{
    if( hingeAngle < 0.001 )
    {
        // No hinge => full circle
        return sdWireCircle(pLocal, R, wt);
    }

    float topDist    = 1e6;
    float bottomDist = 1e6;

    // top half => y>=0
    if(pLocal.y >= 0.)
    {
        topDist = sdWireCircle(pLocal, R, wt);
    }

    // bottom half => pivot=(R,0,0), rotate around that pivot
    {
        vec3 pivot = vec3(R,0.,0.);
        vec3 pp    = pLocal - pivot;
               pp  = rotateY(-hingeAngle)*pp;
               pp += pivot;

        if(pp.y < 0.)
        {
            bottomDist = sdWireCircle(pp, R, wt);
        }
    }
    return min(topDist,bottomDist);
}

//-----------------------------------------
// Phase1 => front & back ring
//-----------------------------------------
float getFrontRingSDF_Phase1(vec3 p, float t)
{
    float R   = 1.0;
    float wt  = 0.02;
    float deg = 0.;

    // t=2..4 => hinge from 0..90
    if(t >= 2. && t < 4.)
    {
        float alpha = (t - 2.) / 2.;
        deg = mix(0., 90., alpha);
    }
    else if(t >= 4.)
    {
        deg = 90.;
    }
    return getHingedRingSDF(p, R, wt, radians(deg));
}

float getBackRingSDF_Phase1(vec3 p, float t)
{
    float R   = 1.0;
    float wt  = 0.02;

    // Move behind => p+vec3(0,0,2), then rotateY(180)
    vec3 p2 = p + vec3(0.,0.,2.);
         p2 = rotateY(PI)*p2;

    float deg = 0.;
    if(t >= 4. && t < 6.)
    {
        float alpha = (t - 4.) / 2.;
        deg = mix(0., 90., alpha);
    }
    else if(t >= 6.)
    {
        deg = 90.;
    }
    return getHingedRingSDF(p2, R, wt, radians(deg));
}

// Combine front/back ring in Phase1
float getSceneSDF_Phase1(vec3 p, float t)
{
    float dF = getFrontRingSDF_Phase1(p, t);
    float dB = (t < 4.) ? 1e6 : getBackRingSDF_Phase1(p, t);
    return min(dF,dB);
}

//-----------------------------------------
// Early spin t=0..2 => around the ORIGIN
//-----------------------------------------
vec3 doEarlyPirouette(vec3 p, float t)
{
    // No pivot shift; just spin about origin if t<2
    if(t < 2.)
    {
        // 2 revolutions in 2 seconds => angle=0..4π
        float angle = 4.0 * PI * (t / 2.);
        p = rotateY(angle)*p;
    }
    return p;
}

//-----------------------------------------
// Phase2 pivot rotation t=6..9 => 0..45 deg
//  pivot around (0,0.5,-1.)
//-----------------------------------------
vec3 applyGlobalRotation_Phase2(vec3 p, float t)
{
    vec3 pivot = vec3(0., 0.5, -1.);
    p -= pivot;

    // t=6..9 => angle 0..45
    float dt   = clamp(t - 6., 0., 3.);
    float angle= mix(0., radians(45.), dt/3.);
    p = rotateY(angle)*p;

    p += pivot;
    return p;
}

//-----------------------------------------
// In Phase2 => ring fully open => hinge=90
//-----------------------------------------
float getFrontRingSDF_Phase2(vec3 p)
{
    return getHingedRingSDF(p, 1., 0.02, radians(90.));
}

float getBackRingSDF_Phase2(vec3 p)
{
    vec3 p2 = p + vec3(0.,0.,2.);
         p2 = rotateY(PI)*p2;
    return getHingedRingSDF(p2, 1., 0.02, radians(90.));
}

//-----------------------------------------
// (Removed) Final infinite spin => just pass p
//-----------------------------------------
vec3 applyFinalInfiniteSpin(vec3 p, float t)
{
    return p;
}

//-----------------------------------------
// Phase2 => union front/back
//-----------------------------------------
float getSceneSDF_Phase2(vec3 p, float t)
{
    // pivot from t=6..9
    p = applyGlobalRotation_Phase2(p, t);

    // final spin => removed
    // p = applyFinalInfiniteSpin(p, t);

    float dF = getFrontRingSDF_Phase2(p);
    float dB = getBackRingSDF_Phase2(p);
    return min(dF, dB);
}

//-----------------------------------------
// Master SDF => phases
//-----------------------------------------
float getSceneSDF(vec3 p, float t)
{
    // early spin 0..2
    p = doEarlyPirouette(p, t);

    if(t < 6.)
    {
        return getSceneSDF_Phase1(p, t);
    }
    else
    {
        return getSceneSDF_Phase2(p, t);
    }
}

//-----------------------------------------
// Raymarch & Normal
//-----------------------------------------
vec3 raymarch(vec3 ro, vec3 rd, float t)
{
    float distAcc = 0.;
    const float MAX_DIST = 50.;

    for(int i=0; i<128; i++)
    {
        vec3 pos = ro + rd*distAcc;
        float d  = getSceneSDF(pos, t);
        if(abs(d) < 0.0001)
        {
            return pos; // hit
        }
        distAcc += d;
        if(distAcc > MAX_DIST) break;
    }
    return ro + rd*MAX_DIST; // no hit => background
}

// SDF sample
float sampleSDF(vec3 p, float t)
{
    return getSceneSDF(p, t);
}

// Normal
vec3 getNormal(vec3 p, float t)
{
    float baseVal = sampleSDF(p, t);
    vec2 e = vec2(0.001,0.);
    float nx = sampleSDF(p + vec3(e.x,e.y,e.y), t) - baseVal;
    float ny = sampleSDF(p + vec3(e.y,e.x,e.y), t) - baseVal;
    float nz = sampleSDF(p + vec3(e.y,e.y,e.x), t) - baseVal;
    return normalize(vec3(nx, ny, nz));
}

//-----------------------------------------
// mainImage => includes loop with 4s pause
//-----------------------------------------
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // 1) We'll do a 9-second animation + 4-second pause => 13s cycle
    float ANIM_DURATION = 9.0;   // full ring animation
    float PAUSE_DURATION= 4.0;   // freeze at end
    float CYCLE         = ANIM_DURATION + PAUSE_DURATION;

    // 2) Real time => wrap with mod
    float realT = iTime;
    float tWrapped = mod(realT, CYCLE);

    // 3) If in the last 4s, freeze at final pose
    float t;
    if(tWrapped <= ANIM_DURATION)
    {
        t = tWrapped;  // normal animation from 0..9
    }
    else
    {
        t = ANIM_DURATION; // freeze from 9..13
    }


    vec3 AA;
    AA.z = 0.0;
    vec3 color = vec3(0);
    for (AA.x = -1.0; AA.x <= 1.0; AA.x += 1.0) {
    for (AA.y = -1.0; AA.y <= 1.0; AA.y += 1.0) {

    vec2 FC = fragCoord + AA.xy / 3.0;
    AA.z += 1.0;

    //------------------------------------------------
    //  Camera & Ray
    //------------------------------------------------
    vec2 uv = (FC - 0.5*iResolution.xy) / iResolution.y;


    // camera: ro=(0,0,20), target=(0,0,0)
    vec3 ro = vec3(0.,0.,20.);
    vec3 ta = vec3(0.,0., 0.);

    vec3 fw = normalize(ta - ro);
    vec3 cp = vec3(0.,1.,0.);
    vec3 rt = normalize(cross(fw, cp));
    vec3 up = cross(rt, fw);

    // For t>6 => camera tilts up to 90 deg in 1s (6..7)
    if(t > 6.)
    {
        float dt = t - 6.;
        float camAngle = min(dt, 1.5708); // up to 90 deg
        float c = cos(camAngle), s = sin(camAngle);

        rt = vec3(c*rt.x - s*rt.y, s*rt.x + c*rt.y, rt.z);
        up = vec3(c*up.x - s*up.y, s*up.x + c*up.y, up.z);
    }

    // narrower FOV => "orthographic" feel
    vec2 uvScaled = uv * 0.15;
    vec3 rd = normalize(rt*uvScaled.x + up*uvScaled.y + fw);

    //------------------------------------------------
    //  Raymarch
    //------------------------------------------------
    vec3 hitPos = raymarch(ro, rd, t);

    // if too far => background
    if(distance(hitPos, ro) > 49.9)
    {
        color += vec3(0.820);
        continue;
    }

    //------------------------------------------------
    // Shading
    //------------------------------------------------
    vec3 n = getNormal(hitPos, t);
    vec3 lightDir = normalize(vec3(0.000,1.000,0.667));
    float diff = max(dot(n, lightDir), 0.);
    color += vec3(1.000,1.000,1.000)*diff + 0.2;

    }}

    color /= AA.z; // Thanks to elenzil!!

    fragColor = vec4(color, 0.0);
}
